+        let (sent, received) = std::sync::mpsc::channel();
+        let waiter = thread::spawn(move || sent.send(server.join().is_ok()).unwrap());
+        let stopped = received.recv_timeout(Duration::from_secs(1)).is_ok();
+        if !stopped {
+            // Release the old fixed-count server so a failing regression cannot
+            // strand its joiner or the test runner in accept().
+            for route in ["GET /mb/recording/second", "POST /lookup", "GET /mb/recording/first", "GET /mb/release/album"] {
+                send(route);
+            }
+        }
+        waiter.join().unwrap();
+        assert!(stopped, "fixture waited for requests the resolver never sent");
